+    assertThat(keyValue.hasValue()).isTrue();
+
+    Entry loneKey = Entry.forLoneKey("key");
+    assertThat(loneKey.getKey()).isEqualTo("key");
+    assertThat(loneKey.getValue()).isNull();
+    assertThat(loneKey.hasValue()).isFalse();
+  }
